    "process:moment-countdown",
    "process:moment-occurs"
   ]
  },
  {
   "component": "moment",
   "field": "every_ticks",
   "held_by": [
    "moment"
   ],
   "written_by_compiled": []
  },
  {
   "component": "moment",
   "field": "occurrences",
   "held_by": [
    "moment"
   ],
   "written_by_compiled": [
    "process:moment-occurs"
   ]
  }
 ],
 "moves": [
  {
   "kind": "communicate",
   "description": "Deliver one represented information item to its declared recipient.",
   "compiled": true
  },
  {
   "kind": "record-assent",
