        {
          "name": "claim",
          "type": "entity_ref"
        }
      ],
      "kind": "investigate-claim"
    },
    {
      "description": "Create an attributed report about a claim addressed to a named recipient. The report may be a warning, including a false warning; delivery remains a separate action.",
      "fields": [
        {
          "name": "recipient",
          "type": "entity_ref"
        },
        {
          "name": "claim",
          "type": "entity_ref"
        }
      ],
      "kind": "author-report"
    }
  ],
  "allowed_state_paths": [
    "location.location_id",
    "ownership.owner_ref",
    "portable.portable",
    "components.member.role",
    "components.member.authorized",
    "components.member.approved",
    "components.member.aware",
    "components.information.content",
